SELECT bb.BOOKSET_ID AS booksetId, #{HAPPEN_DATE} as happenDate, bb.STANDARD_CCY as standardCcy, bb.BOOKSET_NAME as booksetName, bb.BOOKSET_FULLNAME as booksetFullname, bb.ACCT_MODE as acctMode, bb.BOK_SPEC_MODE as bokSpecMode, bb.ACCT_SUBJECT_ID as acctSubjectId, fin.FINPROD_NAME as finprodName FROM BOK_BOOKSET bb INNER JOIN FIN_PRODUCT fin ON fin.FINPROD_ID = bb.BOOKSET_ID WHERE bb.bookset_type = #{booksetType} AND BB.END_DATE >= #{HAPPEN_DATE}
AND (bb.BOOKSET_ID IN
null) OR bb.BOOKSET_ID in (
#{item}
)

DELETE
FROM VAL_TABLE_BAS
WHERE BOOKSET_ID = #{booksetId,jdbcType=VARCHAR}
  and CDATE = #{happenDate}

DELETE
FROM VAL_TABLE_INS
WHERE BOOKSET_ID = #{booksetId,jdbcType=VARCHAR}
  and CDATE = #{happenDate}

DELETE
FROM VAL_TABLE_SCOE
WHERE BOOKSET_ID = #{booksetId,jdbcType=VARCHAR}
  and CDATE = #{happenDate}

select 
from BOK_BALANCE bb
where bb.BOOKSET_ID = #{booksetId}
and bb.SUBJECT_NO like '6%'
and bb.BALANCE_DATE = #{balanceDate}

SELECT
FROM bok_balance bb /*科目余额表*/ LEFT JOIN BOK_BOOKSET bbs on bb.BOOKSET_ID = bbs.BOOKSET_ID LEFT JOIN bok_subject bs /*账套科目表*/ ON bbs.BOOKSET_ID_TMPL = bs.bookset_id AND bb.subject_no = bs.subject_no WHERE 1=1 and bb.bookset_id = #{booksetId} and bs.subject_level = '1'
AND bb.balance_date = #{vdate}
AND bb.balance_date > #{vdate} AND bb.balance_date <= #{mdate}
group by bb.BOOKSET_ID, bb.SUBJECT_NO, bs.SUBJECT_NAME, bs.subject_type, bb.SUBJECT_LEVEL, bb.BAL_FLAG
